1274→+/**
1275→+ * Publish an IPNS record and verify it is resolvable.
1276→+ *
1277→+ * Wraps createAndPublishIpnsRecord with a resolve-back verification loop.
1278→+ * On verify failure, retries with exponential backoff (500ms, 1000ms, 2000ms).
1279→+ * After all retries exhausted, does NOT throw -- the publish went through,
1280→+ * verification just couldn't confirm propagation.
1281→+ */
1282→+async function publishWithVerify(params: {
1283→+  ipnsName: string;
1284→+  ipnsPrivateKey: Uint8Array;
1285→+  cid: string;
1286→+  sequenceNumber: bigint;
1287→+  encryptedIpnsPrivateKey?: string;
1288→+  keyEpoch?: number;
1289→+  ctx: SdkContext;
1290→+  maxRetries?: number;
1291→+}): Promise<void> {
1292→+  const maxRetries = params.maxRetries ?? 3;
1293→+  for (let attempt = 0; attempt < maxRetries; attempt++) {
1294→+    await sdkCore.createAndPublishIpnsRecord({
1295→+      ipnsPrivateKey: params.ipnsPrivateKey,
1296→+      ipnsName: params.ipnsName,
1297→+      metadataCid: params.cid,
1298→+      sequenceNumber: params.sequenceNumber,
1299→+      encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
1300→+      keyEpoch: params.keyEpoch,
1301→+      ctx: params.ctx,
1302→+    });
1303→+    // Verify: resolve back to confirm DB cache was written
1304→+    const resolved = await sdkCore.resolveIpnsRecord(params.ipnsName, params.ctx);
1305→+    if (resolved) return; // Success -- record is resolvable
1306→+    // Exponential backoff: 500ms, 1000ms, 2000ms
1307→+    if (attempt < maxRetries - 1) {
1308→+      await new Promise((r) => setTimeout(r, 500 * Math.pow(2, attempt)));
1309→+    }
1310→+  }
1311→+  // After all retries, don't throw -- the publish went through, just verification failed
1312→+  // The record may still propagate eventually
1313→+}
