 1→/**
 2→ * @cipherbox/crypto - Encoding Utilities
 3→ *
 4→ * Hex and byte conversion utilities.
 5→ */
 6→
 7→/**
 8→ * Convert hex string to Uint8Array.
 9→ * Handles optional 0x prefix.
10→ *
11→ * @param hex - Hex string (with or without 0x prefix)
12→ * @returns Byte array
13→ */
14→export function hexToBytes(hex: string): Uint8Array {
15→  const cleanHex = hex.startsWith('0x') ? hex.slice(2) : hex;
16→
17→  if (cleanHex.length % 2 !== 0) {
18→    throw new Error('Invalid hex string: odd length');
19→  }
20→
21→  const bytes = new Uint8Array(cleanHex.length / 2);
22→  for (let i = 0; i < bytes.length; i++) {
23→    const byte = parseInt(cleanHex.substring(i * 2, i * 2 + 2), 16);
24→    if (Number.isNaN(byte)) {
25→      throw new Error('Invalid hex string: non-hex character');
26→    }
27→    bytes[i] = byte;
28→  }
29→
30→  return bytes;
31→}
32→
33→/**
34→ * Convert Uint8Array to hex string (no prefix).
35→ *
36→ * @param bytes - Byte array
37→ * @returns Hex string without 0x prefix
38→ */
39→export function bytesToHex(bytes: Uint8Array): string {
40→  return Array.from(bytes)
41→    .map((b) => b.toString(16).padStart(2, '0'))
42→    .join('');
43→}
44→
45→/**
46→ * Concatenate multiple Uint8Arrays into one.
47→ *
48→ * @param arrays - Arrays to concatenate
49→ * @returns Combined array
50→ */
51→export function concatBytes(...arrays: Uint8Array[]): Uint8Array {
52→  const totalLength = arrays.reduce((sum, arr) => sum + arr.length, 0);
53→  const result = new Uint8Array(totalLength);
54→
55→  let offset = 0;
56→  for (const arr of arrays) {
57→    result.set(arr, offset);
58→    offset += arr.length;
59→  }
60→
61→  return result;
62→}
