109→      const userKeypair = await getVaultKeypair();
110→
111→      if (!userKeypair) {
112→        throw new Error('Failed to get vault keypair from Core Kit');
113→      }
114→
115→      // Store keypair in auth store for crypto operations
116→      setVaultKeypair(userKeypair);
117→
118→      // Isolate getVault() so only its 404 triggers new-user initialization.
119→      // Downstream errors (IPNS resolve, IPFS fetch) must not be misclassified.
120→      let existingVault: Awaited<ReturnType<typeof vaultApi.getVault>> | null = null;
121→      try {
122→        existingVault = await vaultApi.getVault();
123→      } catch (error) {
124→        const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
125→        if (!is404) {
126→          console.error('[useAuth] Failed to load vault:', error);
127→          throw error;
128→        }
129→      }
130→
131→      if (existingVault) {
132→        // Store TEE keys if available
133→        if (existingVault.teeKeys) {
134→          useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
135→        }
136→
137→        // Read rootFolderKey from dedicated vault key IPNS (separate from root folder IPNS)
138→        const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(userKeypair.privateKey);
139→
140→        const resolved = await resolveIpnsRecord(vaultKeyKeypair.ipnsName);
141→        if (!resolved) throw new Error('Vault key IPNS name not found');
142→
143→        const blobBytes = await fetchFromIpfs(resolved.cid);
144→
145→        if (detectBlobVersion(blobBytes) !== 2) {
146→          throw new Error('Vault key blob is not v2 format');
147→        }
148→
149→        const encKey = deserializeVaultBlobV2(blobBytes);
150→        const rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);
151→
152→        // Root folder IPNS keypair is the original vault derivation
153→        const rootIpnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
154→
155→        setVaultKeys({
156→          rootFolderKey,
157→          rootIpnsKeypair,
158→          rootIpnsName: existingVault.rootIpnsName,
159→          vaultId: existingVault.id,
160→        });
161→      } else {
162→        // New user -- initialize vault with separate key blob + folder metadata
163→        console.log('[Auth] New user -- initializing vault');
164→        const newVault = await initializeVault(userKeypair.privateKey);
165→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
166→
167→        // Derive vault key IPNS keypair (separate from root folder IPNS)
168→        const vaultKeyKeypair = await deriveVaultKeyIpnsKeypair(userKeypair.privateKey);
169→        const vaultKeyIpnsName = vaultKeyKeypair.ipnsName;
170→
171→        // 1. Publish v2 key blob to vault key IPNS (rootFolderKey storage — key only, no metadata)
172→        const encryptedRootFolderKey = await wrapKey(newVault.rootFolderKey, userKeypair.publicKey);
173→        const v2Blob = serializeVaultBlobV2(encryptedRootFolderKey);
174→
175→        const keyBlobUpload = await addToIpfs(new Blob([v2Blob as BlobPart]));
176→        const keyPublishResult = await createAndPublishIpnsRecord({
177→          ipnsPrivateKey: vaultKeyKeypair.privateKey,
178→          ipnsName: vaultKeyIpnsName,
179→          metadataCid: keyBlobUpload.cid,
180→          sequenceNumber: 0n,
181→          expectedSequenceNumber: undefined,
182→        });
183→        if (!keyPublishResult.success) {
184→          throw new Error('Failed to publish vault key blob to IPNS');
185→        }
