223→      // Load BYO pinning config from encrypted IPNS entry (if configured).
224→      // Gracefully degrades to cipherbox-only mode on any failure.
225→      const loadByoConfig = async (
226→        userPrivateKey: Uint8Array
227→      ): Promise<PinningConfig | undefined> => {
228→        // Time-bound the entire lookup so a hung IPFS peer can't block login
229→        const BYO_LOAD_TIMEOUT_MS = 10_000;
230→        const inner = async (): Promise<PinningConfig | undefined> => {
231→          const byoKeypair = await deriveByoConfigIpnsKeypair(userPrivateKey);
232→          const ipnsName = byoKeypair.ipnsName;
233→
234→          const resolved = await resolveIpnsRecord(ipnsName);
235→          if (!resolved?.cid) return undefined;
236→
237→          const encrypted = await fetchFromIpfs(resolved.cid);
238→          const plaintext = await unwrapKey(encrypted, userPrivateKey);
239→          let config: ByoIpfsConfig;
240→          try {
241→            const json = new TextDecoder().decode(plaintext);
242→            config = JSON.parse(json) as ByoIpfsConfig;
243→          } finally {
244→            clearBytes(plaintext);
245→          }
246→
247→          // Runtime validation: ensure the blob has a valid shape
248→          const validModes = ['cipherbox', 'external', 'dual'];
249→          if (!config.pinningMode || !validModes.includes(config.pinningMode)) {
250→            return undefined;
251→          }
252→          if (config.pinningMode !== 'cipherbox' && !config.externalProvider?.endpoint) {
253→            return undefined;
254→          }
255→
256→          return {
257→            mode: config.pinningMode,
258→            externalProvider: config.externalProvider ?? undefined,
259→          };
260→        };
261→
262→        try {
263→          const result = await Promise.race([
264→            inner(),
265→            new Promise<undefined>((resolve) =>
266→              setTimeout(() => resolve(undefined), BYO_LOAD_TIMEOUT_MS)
267→            ),
268→          ]);
269→          return result;
270→        } catch {
271→          // No BYO config or decryption failed -- default to cipherbox-only
272→          return undefined;
273→        }
274→      };
