276→      // Initialize SDK client with decrypted vault keys
277→      const vaultState = useVaultStore.getState();
278→      const authState = useAuthStore.getState();
279→      if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
