289→        // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
290→
291→        const sdkClient = initSdkClient({
292→          apiUrl,
293→          getAccessToken,
294→          vaultKeypair: {
295→            publicKey: userKeypair.publicKey,
296→            privateKey: userKeypair.privateKey,
297→          },
298→          rootIpnsName: vaultState.rootIpnsName,
299→          rootFolderKey: vaultState.rootFolderKey,
300→          teeKeys: authState.teeKeys ?? undefined,
301→          pinningConfig,
302→          shareCallbacks: {
