306→              // Find the folder ID from IPNS name for ancestor traversal
307→              const folderId =
308→                Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
309→              return findCoveringShares(folderIpnsName, folders, folderId);
310→            },
311→            addShareKeys: async (shareId, keys) => {
312→              const { addShareKeys } = await import('../services/share.service');
