314→            },
315→          },
316→        });
317→
318→        // Subscribe folder store to SDK events
319→        useFolderStore.getState().subscribeToSdk(sdkClient);
320→
321→        // Subscribe bin store to SDK events
322→        useBinStore.getState().subscribeToSdk(sdkClient);
323→      }
324→
325→      // Non-blocking device registry initialization (fire-and-forget)
326→      // Placed after vault load so registry failures never block login
327→      void (async () => {
328→        try {
329→          const deviceKeypair = await getOrCreateDeviceIdentity({
330→            mode: 'persisted',
331→            vaultPrivateKey: userKeypair.privateKey,
332→          });
333→          const deviceInfo = detectDeviceInfo();
334→          // Compute ipHash for device registration (privacy-preserving placeholder)
335→          const ipHashBuffer = await crypto.subtle.digest(
336→            'SHA-256',
337→            new TextEncoder().encode('0.0.0.0')
338→          );
339→          const ipHashHex = Array.from(new Uint8Array(ipHashBuffer))
340→            .map((b) => b.toString(16).padStart(2, '0'))
341→            .join('');
342→          const result = await initializeOrSyncRegistry({
343→            userPrivateKey: userKeypair.privateKey,
344→            userPublicKey: userKeypair.publicKey,
