356→      })();
357→
358→      // Non-blocking bin initialization (fire-and-forget)
359→      // After old service creates/loads bin, also load into SDK for deleteToBin support
360→      void (async () => {
361→        try {
362→          await initializeBin({
363→            userPrivateKey: userKeypair.privateKey,
