371→        } catch (error) {
372→          console.error('[Auth] Bin initialization failed (non-blocking):', error);
373→        }
374→      })();
375→
376→      // Non-blocking: fetch retention config from API
377→      void (async () => {
378→        try {
379→          const config = await vaultControllerGetConfig();
