385→        }
386→      })();
387→    };
388→    vaultInitPromise = doInit().finally(() => {
389→      vaultInitPromise = null;
390→    });
391→    return vaultInitPromise;
392→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
