394→  /**
395→   * Complete backend authentication after Core Kit login.
396→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
397→   * to the backend with loginType 'corekit'. The backend verifies it against
398→   * its own JWKS since CipherBox is the identity provider.
399→   */
400→  const completeBackendAuth = useCallback(
401→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
402→      // 1. Get real publicKey from Core Kit TSS export
403→      const publicKey = await getPublicKeyHex();
404→      if (!publicKey) {
405→        throw new Error('Failed to get publicKey from Core Kit');
406→      }
407→
408→      // publicKey available for debugging via DevTools if needed
409→
410→      // 2. Authenticate with CipherBox backend
411→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
412→      const response = await authApi.login({
413→        idToken: cipherboxJwt,
414→        publicKey,
415→        loginType: 'corekit',
416→      });
417→
418→      // 3. Store access token (refresh token in HTTP-only cookie)
419→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
420→      // are fully initialized to prevent Login.tsx from redirecting to /files
421→      // before the SDK client is ready for file operations.
422→      setAccessToken(response.accessToken);
423→
424→      // 4. Remember auth method for UX
425→      setLastAuthMethod(authMethod);
426→
427→      // 5. Initialize or load vault + SDK client
428→      await initializeOrLoadVault();
429→
430→      // 6. Now that vault keys are loaded and SDK is initialized,
431→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
432→      setAuthenticated();
433→    },
434→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
435→  );
436→
437→  /**
438→   * Complete the login flow after REQUIRED_SHARE is resolved.
439→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
440→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
441→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
442→   */
443→  const completeRequiredShare = useCallback(async (): Promise<void> => {
444→    // Read directly from Zustand store to get fresh values — this callback
445→    // may be called from useDeviceApproval's useAuth() instance, so we
446→    // can't rely on closure-captured selector values.
447→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
448→
449→    if (!jwt || !method) {
450→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
451→    }
452→
453→    // Core Kit should now be LOGGED_IN after inputFactorKey()
454→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
455→    await completeBackendAuth(method, jwt);
456→
457→    // NOW sync Core Kit React state to LOGGED_IN.
458→    // We deliberately delayed this from inputFactorKey() to prevent the session
459→    // restoration effect from firing before backend auth completed.
460→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
461→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
462→    syncStatus();
463→
464→    // Clear pending state
465→    setPendingAuth(null, null);
466→
467→    // Navigate to files
468→    navigate('/files');
469→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
