471→  /**
472→   * Login with Google OAuth token.
473→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
474→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
475→   */
476→  const loginWithGoogle = useCallback(
477→    async (googleIdToken: string): Promise<void> => {
478→      if (isLoggingIn) return;
479→      setIsLoggingIn(true);
480→      try {
481→        // 1. Core Kit login via CipherBox identity provider
482→        const {
483→          cipherboxJwt,
484→          email,
485→          userId,
486→          status: coreKitStatus,
487→        } = await coreKitLoginGoogle(googleIdToken);
488→
489→        if (coreKitStatus === 'required_share') {
490→          // MFA enabled but device factor missing.
491→          // Store pending auth info for later completion after factor input.
492→          setPendingAuth(cipherboxJwt, 'google');
493→
494→          // Obtain temporary backend access token so the new device can
495→          // call bulletin board API endpoints (device-approval/*).
496→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
497→          // state and we can't export the TSS key yet.
498→          const tempLoginResponse = await authApi.login({
499→            idToken: cipherboxJwt,
500→            publicKey: `pending-core-kit-${userId}`,
501→            loginType: 'corekit',
502→          });
503→          setAccessToken(tempLoginResponse.accessToken);
504→
505→          if (email) {
506→            setUserEmail(email);
507→          }
508→
509→          // Do NOT call completeBackendAuth() or navigate('/files')
510→          // The component tree will see isRequiredShare === true and
511→          // render recovery/approval UI.
512→          return;
513→        }
514→
515→        // Normal path: Core Kit logged in, proceed as before
516→        // 2. Complete backend auth + vault init
517→        await completeBackendAuth('google', cipherboxJwt);
518→
519→        // 3. Store email for UI display (returned from identity endpoint)
520→        if (email) {
521→          setUserEmail(email);
522→        }
523→
524→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
525→      } catch (error) {
526→        console.error('[useAuth] Google login failed:', error);
527→        throw error;
528→      } finally {
529→        setIsLoggingIn(false);
530→      }
531→    },
532→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
533→  );
534→
535→  /**
536→   * Login with Email OTP.
537→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
538→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
539→   */
540→  const loginWithEmail = useCallback(
541→    async (email: string, otp: string): Promise<void> => {
542→      if (isLoggingIn) return;
543→      setIsLoggingIn(true);
544→      try {
545→        // 1. Core Kit login via CipherBox identity provider
546→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
547→
548→        if (coreKitStatus === 'required_share') {
549→          setPendingAuth(cipherboxJwt, 'email');
550→
551→          const tempLoginResponse = await authApi.login({
552→            idToken: cipherboxJwt,
553→            publicKey: `pending-core-kit-${userId}`,
554→            loginType: 'corekit',
555→          });
556→          setAccessToken(tempLoginResponse.accessToken);
557→          setUserEmail(email);
558→          return;
559→        }
560→
561→        // Normal path
562→        await completeBackendAuth('email', cipherboxJwt);
563→        setUserEmail(email);
564→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
565→      } catch (error) {
566→        console.error('[useAuth] Email login failed:', error);
567→        throw error;
568→      } finally {
569→        setIsLoggingIn(false);
570→      }
571→    },
572→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
573→  );
574→
575→  /**
576→   * Login with Wallet (SIWE).
577→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
578→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
579→   */
580→  const loginWithWallet = useCallback(
581→    async (cipherboxJwt: string, userId: string): Promise<void> => {
582→      if (isLoggingIn) return;
583→      setIsLoggingIn(true);
584→      try {
585→        // 1. Core Kit login via CipherBox identity provider
586→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
587→
588→        if (coreKitStatus === 'required_share') {
589→          setPendingAuth(cipherboxJwt, 'wallet');
590→
591→          const tempLoginResponse = await authApi.login({
592→            idToken: cipherboxJwt,
593→            publicKey: `pending-core-kit-${userId}`,
594→            loginType: 'corekit',
595→          });
596→          setAccessToken(tempLoginResponse.accessToken);
597→          return;
598→        }
599→
600→        // Normal path
601→        await completeBackendAuth('wallet', cipherboxJwt);
602→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
603→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
604→        // inside it may still be pending. An explicit navigate here would fire AFTER
605→        // vault init completes — by which point the user may have navigated away from
606→        // the login page, causing a disruptive late redirect.
607→      } catch (error) {
608→        console.error('[useAuth] Wallet login failed:', error);
609→        throw error;
610→      } finally {
611→        setIsLoggingIn(false);
612→      }
613→    },
614→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
615→  );
616→
617→  // Complete logout: Backend -> Core Kit -> Clear state
618→  const logout = useCallback(async () => {
619→    if (isLoggingOut) return;
620→
621→    setIsLoggingOut(true);
622→    try {
623→      // 1. Call backend logout (clears cookie)
624→      if (accessToken) {
625→        try {
626→          await authApi.logout();
627→        } catch {
628→          // Ignore errors -- we'll clear state anyway
629→        }
630→      }
631→
632→      // 2. Logout Core Kit (clears session from localStorage)
633→      await coreKitLogout();
634→
635→      // 3. Clear all user-scoped stores (centralized helper)
636→      clearAllUserStores();
637→
638→      // 4. Navigate to login
639→      navigate('/');
640→    } catch (error) {
641→      console.error('[useAuth] Logout failed:', error);
642→      // Still clear state even if backend fails
643→      clearAllUserStores();
644→      navigate('/');
645→    } finally {
646→      setIsLoggingOut(false);
647→    }
648→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
649→
650→  // Keep function refs up-to-date for use in session restoration effect.
651→  // Using refs prevents the effect from re-firing when function identities change.
652→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
653→  coreKitLogoutRef.current = coreKitLogout;
654→
655→  // Session restoration: if Core Kit restores a session from localStorage
656→  // on init, we have LOGGED_IN status without going through login flow.
657→  // Complete backend auth + vault loading.
658→  useEffect(() => {
659→    const restoreSession = async () => {
660→      // Only restore if Core Kit has a session but we don't have
661→      // a backend access token yet
662→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
663→        restoringRef.current = true;
664→        setIsLoggingIn(true);
665→        try {
666→          // Try to refresh using the HTTP-only cookie first
667→          const response = await authApi.refresh();
668→          setAccessToken(response.accessToken);
669→
670→          // Restore email from backend if available
671→          if (response.email) {
672→            setUserEmail(response.email);
673→          }
674→
675→          // Load vault keys from Core Kit keypair + initialize SDK
676→          await initializeOrLoadVaultRef.current?.();
677→
678→          // Mark as authenticated only after vault + SDK are ready
679→          setAuthenticated();
680→        } catch {
681→          // No valid backend session -- user needs to re-login
682→          // Core Kit session exists but backend cookie expired
683→          // Clear Core Kit session to avoid inconsistent state
684→          try {
685→            await coreKitLogoutRef.current?.();
686→          } catch {
687→            // Ignore logout errors during cleanup
688→          }
689→        } finally {
690→          restoringRef.current = false;
691→          setIsLoggingIn(false);
692→        }
693→      }
694→    };
695→    restoreSession();
696→  }, [
697→    coreKitLoggedIn,
698→    isAuthenticated,
699→    isLoggingIn,
700→    setAccessToken,
701→    setAuthenticated,
702→    setUserEmail,
703→  ]);
704→
705→  return {
706→    isLoading,
707→    isAuthenticated,
708→    isRequiredShare,
709→    lastAuthMethod,
710→    userEmail,
711→    pendingAuthMethod,
712→    loginWithGoogle,
713→    loginWithEmail,
714→    loginWithWallet,
715→    completeRequiredShare,
716→    logout,
717→  };
718→}
