  1→/**
  2→ * Device Info Detection
  3→ *
  4→ * Auto-detects device metadata from the browser environment.
  5→ * Used to populate the device entry when registering in the
  6→ * encrypted device registry.
  7→ */
  8→
  9→import type { DevicePlatform } from '@cipherbox/core';
 10→import { bytesToHex, CRYPTO_VERSION } from '@cipherbox/crypto';
 11→
 12→/**
 13→ * Auto-detect device information from the browser environment.
 14→ *
 15→ * Returns platform-appropriate metadata for the device registry entry.
 16→ * Device name and model are kept simple -- users can rename in Settings.
 17→ *
 18→ * @returns Device metadata for registry registration
 19→ */
 20→export function detectDeviceInfo(): {
 21→  name: string;
 22→  platform: DevicePlatform;
 23→  appVersion: string;
 24→  deviceModel: string;
 25→} {
 26→  const ua = navigator.userAgent;
 27→
 28→  // Detect platform
 29→  const platform = detectPlatform(ua);
 30→
 31→  // Detect browser name
 32→  const browserName = detectBrowser(ua);
 33→
 34→  // Detect OS name + version
 35→  const osInfo = detectOS(ua);
 36→
 37→  // Device name: "Chrome on macOS" style
 38→  const name = `${browserName} on ${osInfo.name}`;
 39→
 40→  // Device model: "Chrome 123 on macOS 15.2" style
 41→  const deviceModel = `${browserName} on ${osInfo.name}${osInfo.version ? ` ${osInfo.version}` : ''}`;
 42→
 43→  // App version: prefer VITE_APP_VERSION env var, fall back to CRYPTO_VERSION
 44→  const appVersion = import.meta.env.VITE_APP_VERSION || CRYPTO_VERSION;
 45→
 46→  return { name, platform, appVersion, deviceModel };
 47→}
 48→
 49→/**
 50→ * Detect the platform from the user agent string.
 51→ */
 52→function detectPlatform(ua: string): DevicePlatform {
 53→  if (/Macintosh|Mac OS X/i.test(ua)) return 'macos';
 54→  if (/Windows/i.test(ua)) return 'windows';
 55→  if (/Linux/i.test(ua)) return 'linux';
 56→  return 'web';
 57→}
 58→
 59→/**
 60→ * Detect the browser name from the user agent string.
 61→ */
 62→function detectBrowser(ua: string): string {
 63→  // Order matters -- check more specific browsers first
 64→  if (/Edg\//i.test(ua)) return 'Edge';
 65→  if (/OPR\//i.test(ua) || /Opera/i.test(ua)) return 'Opera';
 66→  if (/Firefox\//i.test(ua)) return 'Firefox';
 67→  if (/Chrome\//i.test(ua)) return 'Chrome';
 68→  if (/Safari\//i.test(ua)) return 'Safari';
 69→  return 'Browser';
 70→}
 71→
 72→/**
 73→ * Detect OS name and version from the user agent string.
 74→ */
 75→function detectOS(ua: string): { name: string; version: string } {
 76→  // macOS
 77→  const macMatch = ua.match(/Mac OS X (\d+[._]\d+(?:[._]\d+)?)/);
 78→  if (macMatch) {
 79→    return { name: 'macOS', version: macMatch[1].replace(/_/g, '.') };
 80→  }
 81→
 82→  // Windows
 83→  const winMatch = ua.match(/Windows NT (\d+\.\d+)/);
 84→  if (winMatch) {
 85→    const ntVersionMap: Record<string, string> = {
 86→      '10.0': '10/11',
 87→      '6.3': '8.1',
 88→      '6.2': '8',
 89→      '6.1': '7',
 90→    };
 91→    const friendlyVersion = ntVersionMap[winMatch[1]] || winMatch[1];
 92→    return { name: 'Windows', version: friendlyVersion };
 93→  }
 94→
 95→  // Linux
 96→  if (/Linux/i.test(ua)) {
 97→    return { name: 'Linux', version: '' };
 98→  }
 99→
100→  return { name: 'Unknown OS', version: '' };
101→}
102→
103→/**
104→ * Compute a privacy-preserving hash of an IP address.
105→ *
106→ * The actual IP is obtained from the backend; this function
107→ * hashes it locally before storing in the registry.
108→ *
109→ * Uses Web Crypto SHA-256 (available in all modern browsers).
110→ *
111→ * @param ipAddress - IP address string (e.g., "192.168.1.1")
112→ * @returns Hex-encoded SHA-256 hash
113→ */
114→export async function computeIpHash(ipAddress: string): Promise<string> {
115→  const data = new TextEncoder().encode(ipAddress);
116→  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
117→  return bytesToHex(new Uint8Array(hashBuffer));
118→}
