363→    function hexToBytes(hex) {
364→      const clean = hex.startsWith('0x') ? hex.slice(2) : hex;
365→      if (clean.length % 2 !== 0) throw new Error('Invalid hex: odd length');
366→      const bytes = new Uint8Array(clean.length / 2);
367→      for (let i = 0; i < bytes.length; i++) {
368→        const b = parseInt(clean.substring(i * 2, i * 2 + 2), 16);
369→        if (Number.isNaN(b)) throw new Error('Invalid hex character');
370→        bytes[i] = b;
371→      }
372→      return bytes;
373→    }
