402→      if (blob[0] !== BLOB_V2_VERSION) throw new Error('Not a v2 vault blob');
403→      const keyLen = (blob[1] << 8) | blob[2];
404→      if (keyLen === 0) throw new Error('Invalid v2 blob: encrypted key length must be > 0');
405→      if (blob.length < 3 + keyLen) throw new Error('Blob too short for key');
