420→     *
421→     * Path: secp256k1 privateKey -> HKDF-SHA256(salt, info) -> 32-byte Ed25519 seed
422→     *       -> Ed25519 public key -> IPNS name (k51...)
423→     */
424→    async function deriveIpnsNameFromKey(userPrivateKey, hkdfInfo) {
425→      const keyMaterial = await crypto.subtle.importKey(
426→        'raw', userPrivateKey, 'HKDF', false, ['deriveBits']
427→      );
428→      const derivedBits = await crypto.subtle.deriveBits(
429→        { name: 'HKDF', hash: 'SHA-256', salt: VAULT_HKDF_SALT, info: hkdfInfo },
430→        keyMaterial, 256
431→      );
432→      const ed25519Seed = new Uint8Array(derivedBits);
433→      const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
434→
435→      // 3. Derive IPNS name from Ed25519 public key
436→      return ed25519PublicKeyToIpnsName(ed25519PublicKey);
437→    }
