439→    // =========================================================================
440→    // Crypto: ECIES Decrypt (matches eciesjs@0.4.16 exactly)
441→    // =========================================================================
442→    async function eciesDecrypt(privKeyBytes, encryptedHex) {
443→      const data = typeof encryptedHex === 'string' ? hexToBytes(encryptedHex) : encryptedHex;
444→
445→      // 1. Extract ephemeral public key (65 bytes, uncompressed, 0x04 prefix)
446→      if (data.length < 65 + 16 + 16) {
447→        throw new Error('ECIES ciphertext too short');
448→      }
449→      const ephemeralPK = data.slice(0, 65);
450→      const payload = data.slice(65);
451→
452→      // 2. Compute ECDH shared point (uncompressed output)
453→      //    eciesjs passes compressed ephemeral PK to getSharedSecret internally
454→      //    but output is uncompressed (compressed=false)
455→      const ephemeralPKCompressed = secp256k1.ProjectivePoint.fromHex(ephemeralPK).toRawBytes(true);
456→      const sharedPoint = secp256k1.getSharedSecret(privKeyBytes, ephemeralPKCompressed, false);
457→
458→      // 3. senderPoint = ephemeral PK uncompressed (65 bytes)
459→      const senderPoint = ephemeralPK;
460→
461→      // 4. Derive shared key: HKDF-SHA256(ikm=senderPoint||sharedPoint, salt=undefined, info=undefined, length=32)
462→      const ikm = concatBytes(senderPoint, sharedPoint);
463→      const sharedKey = hkdf(sha256, ikm, undefined, undefined, 32);
464→
465→      // 5. Extract nonce (16 bytes), tag (16 bytes), ciphertext
466→      const nonce = payload.slice(0, 16);
467→      const tag = payload.slice(16, 32);
468→      const ciphertext = payload.slice(32);
469→
470→      // 6. Decrypt with AES-256-GCM
471→      //    Web Crypto expects ciphertext||tag concatenated
472→      const combined = new Uint8Array(ciphertext.length + tag.length);
473→      combined.set(ciphertext, 0);
474→      combined.set(tag, ciphertext.length);
475→
476→      const cryptoKey = await crypto.subtle.importKey(
477→        'raw', sharedKey, { name: 'AES-GCM' }, false, ['decrypt']
478→      );
479→      const plaintext = await crypto.subtle.decrypt(
480→        { name: 'AES-GCM', iv: nonce }, cryptoKey, combined
481→      );
482→
483→      return new Uint8Array(plaintext);
484→    }
