        // Kubo direct upload flow
        const pinResult = await metrics.measure(
          'byo-pin',
          () => pc.provider.pin(data, `load-${pc.id}-file-${i}`),
          size
        );
        cid = pinResult.cid;
        pinSize = pinResult.size;
